style.css:
@-moz-document url-prefix("https://www.google.com/") {
/* ONLY the Google homepage */
    html[itemtype="http://schema.org/WebPage"] {
        background: #e5b92f !important;
    }

    html[itemtype="http://schema.org/WebPage"] body {
        background-color: transparent !important;
        background-image: url("https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR0utqa7serZU_NWWIsi3qPVS2hcCLzZ4Z_3Wf_mfjoMNl_j3dS") !important;
        background-repeat: no-repeat !important;
        background-position: center top !important;
        background-size: cover !important;
        background-attachment: fixed !important;
    }
}
